from PyQt6.QtWidgets import *
from views.components.widgets import ArrowComboBox
from PyQt6.QtCore import pyqtSignal,Qt

class SettingsView(QWidget):
    save_requested=pyqtSignal(dict); backup_requested=pyqtSignal(); restore_requested=pyqtSignal(); reset_requested=pyqtSignal()
    def __init__(self):
        super().__init__(); outer=QVBoxLayout(self); outer.setContentsMargins(0,0,0,0)
        scroll=QScrollArea(); scroll.setWidgetResizable(True); scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff); scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded); outer.addWidget(scroll)
        page=QWidget(); page.setObjectName('settingsPage'); page.setStyleSheet('QWidget#settingsPage{background:#F2F4F7;color:#111827;}'); scroll.viewport().setStyleSheet('background:#F2F4F7;'); scroll.setWidget(page); root=QVBoxLayout(page); root.setContentsMargins(28,24,28,24); root.setSpacing(14)
        head=QHBoxLayout(); text=QVBoxLayout(); t=QLabel('Configuración'); t.setObjectName('pageTitle'); text.addWidget(t); s=QLabel('Ajusta el funcionamiento del negocio sin exponer detalles técnicos innecesarios.'); s.setObjectName('muted'); s.setWordWrap(True); text.addWidget(s); head.addLayout(text); head.addStretch(); root.addLayout(head)
        basic=QGroupBox('Negocio'); f=QFormLayout(basic); f.setVerticalSpacing(12); f.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow); self.store=QLineEdit(); self.address=QLineEdit(); self.credit=QCheckBox('Permitir ventas fiadas'); f.addRow('Nombre de la tienda',self.store); f.addRow('Dirección',self.address); f.addRow('',self.credit); root.addWidget(basic)
        defaults=QGroupBox('Precios y existencias'); df=QFormLayout(defaults); df.setVerticalSpacing(12); df.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow); self.profit_policy=ArrowComboBox(); self.profit_policy.addItem('Recargo sobre costo','MARKUP'); self.profit_policy.addItem('Margen sobre ventas','MARGIN'); self.profit_policy.currentIndexChanged.connect(self._policy_changed); self.markup=QDoubleSpinBox(); self.markup.setRange(0,1000); self.markup.setDecimals(2); self.markup.setSuffix(' %'); self.markup.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); self.min_stock=QDoubleSpinBox(); self.min_stock.setMaximum(99999); self.min_stock.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); df.addRow('Política de ganancia',self.profit_policy); ph=QLabel('Recargo: precio = costo + porcentaje sobre costo. Margen: porcentaje calculado sobre el precio de venta.'); ph.setObjectName('help'); ph.setWordWrap(True); df.addRow('',ph); df.addRow('Ganancia predeterminada',self.markup); df.addRow('Stock mínimo sugerido',self.min_stock); root.addWidget(defaults)
        adv=QGroupBox('Avanzado'); af=QFormLayout(adv); af.setVerticalSpacing(12); af.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow); self.safety=QDoubleSpinBox(); self.safety.setMaximum(99999); self.safety.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); self.stagnant=QSpinBox(); self.stagnant.setRange(1,3650); self.stagnant.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); self.expiry=QSpinBox(); self.expiry.setRange(1,365); self.expiry.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); self.lead=QSpinBox(); self.lead.setRange(0,365); self.lead.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); self.old_debt=QSpinBox(); self.old_debt.setRange(1,3650); self.old_debt.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons); af.addRow('Stock de seguridad',self.safety); af.addRow('Días para considerar producto estancado',self.stagnant); af.addRow('Avisar vencimiento con días de anticipación',self.expiry); af.addRow('Plazo promedio de proveedores (días)',self.lead); af.addRow('Deuda antigua después de (días)',self.old_debt); root.addWidget(adv)
        row=QHBoxLayout(); save=QPushButton('Guardar configuración'); save.setProperty('class','accent'); save.clicked.connect(lambda:self.save_requested.emit(self.values())); row.addWidget(save); row.addStretch(); b=QPushButton('Crear respaldo'); b.setProperty('class','secondary'); b.clicked.connect(self.backup_requested); row.addWidget(b); r=QPushButton('Restaurar respaldo'); r.setProperty('class','secondary'); r.clicked.connect(self.restore_requested); row.addWidget(r); root.addLayout(row)

        danger=QGroupBox('Reiniciar sistema'); danger.setObjectName('dangerZone'); dl=QVBoxLayout(danger); dl.setSpacing(10)
        warning=QLabel('Esta opción elimina definitivamente productos, inventario, ventas, compras, clientes, fiados, abonos, lotes, historial y configuración. El sistema quedará como recién instalado.'); warning.setObjectName('dangerText'); warning.setWordWrap(True); dl.addWidget(warning)
        hint=QLabel('Antes de usarla, crea un respaldo si existe información que quieras conservar. Los respaldos ya creados no se eliminan.'); hint.setObjectName('help'); hint.setWordWrap(True); dl.addWidget(hint)
        reset=QPushButton('Borrar todos los datos y reiniciar'); reset.setProperty('class','danger'); reset.setMinimumHeight(38); reset.clicked.connect(self.reset_requested); dl.addWidget(reset,0,Qt.AlignmentFlag.AlignLeft)
        root.addWidget(danger); root.addStretch()
    def _policy_changed(self): self.markup.setMaximum(99.99 if self.profit_policy.currentData()=='MARGIN' else 1000)
    def set_values(self,d):
        self.store.setText(d.get('store_name','')); self.address.setText(d.get('store_address','')); self.credit.setChecked(d.get('credit_enabled','1')=='1'); self.markup.setValue(float(d.get('default_markup_pct',25))); self.min_stock.setValue(float(d.get('default_min_stock',5))); self.safety.setValue(float(d.get('safety_stock',3))); self.stagnant.setValue(int(d.get('stagnant_days',60))); self.expiry.setValue(int(d.get('expiry_warning_days',15))); self.lead.setValue(int(d.get('supplier_lead_days',4))); self.old_debt.setValue(int(d.get('old_debt_days',30))); idx=self.profit_policy.findData(d.get('profit_policy','MARKUP')); self.profit_policy.setCurrentIndex(max(0,idx)); self._policy_changed()
    def values(self):
        return {'store_name':self.store.text().strip(),'store_address':self.address.text().strip(),'credit_enabled':'1' if self.credit.isChecked() else '0','default_markup_pct':self.markup.value(),'default_min_stock':self.min_stock.value(),'safety_stock':self.safety.value(),'stagnant_days':self.stagnant.value(),'expiry_warning_days':self.expiry.value(),'supplier_lead_days':self.lead.value(),'old_debt_days':self.old_debt.value(),'profit_policy':self.profit_policy.currentData()}
